            if(lastPauseSerial!=Session.PauseSerial){lastPauseSerial=Session.PauseSerial;if(running!=null&&running.task!=null){object module;running.task.CurrentScope.Root.Try("__name__",out module);string name=module as string;if(name=="__main__")name=running.program;int index=Farm.Data.programs.FindIndex(p=>p.name==name);if(index>=0&&index!=Farm.Data.selectedProgram)Switch(index);int start=0,line=1;while(start<Editor.text.Length&&line<running.line)if(Editor.text[start++]=='\n')line++;int end=Editor.text.IndexOf('\n',start);Editor.selectionStringAnchorPosition=start;Editor.selectionStringFocusPosition=end<0?Editor.text.Length:end;}}
            stateLabel.text=(Session.Error!=""?ClassicDiagnostics.Localize(Session.Error):Session.Running?(Session.Paused?Tr("Paused","已暂停"):Tr("Running","运行中")):Tr("Ready","就绪"))+"  /  "+Tr("Line","行")+" "+(running==null?0:running.line)+"  /  "+Tr("Drones","无人机")+" "+Session.drones.Count(d=>!d.finished)+" / "+Farm.MaxDrones+"  /  "+Session.ticks+" ticks";
            watchLabel.text=running==null?Tr("Ctrl/Cmd+Enter: run  /  F8: language  /  Esc: settings","Ctrl/Cmd+Enter 运行  /  F8 语言  /  Esc 设置"):string.Join("  ",running.task.CurrentScope.values.Where(p=>!p.Key.StartsWith("_")).Take(7).Select(p=>p.Key+"="+ScriptValue.Show(p.Value)));
        }
